// D4 · Part 1 · 잡음이 섞인 음성과 SNR — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d04_snr.ts
//   목표 SNR(20 · 10 · 0 dB)로 잡음을 섞어 실제 SNR을 재고, 잡음 종류(백색 · 핑크 · 험)별 스펙트럼 차이 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
  return out;
}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답

const rnd = mulberry32(0);

function whiteNoise(n: number): Float32Array {
  return Float32Array.from({ length: n }, () => gauss(rnd));
}

function pinkNoise(n: number): Float32Array {
  // 1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (Paul Kellet의 간단한 필터)
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  return Float32Array.from({ length: n }, () => {
    const w = gauss(rnd);
    b0 = 0.99765 * b0 + w * 0.099046;
    b1 = 0.963 * b1 + w * 0.2965164;
    b2 = 0.57 * b2 + w * 1.0526913;
    return b0 + b1 + b2 + w * 0.1848;
  });
}

function humNoise(n: number): Float32Array {
  // 전원 험: 60 Hz와 배음 120 · 180 Hz
  return Float32Array.from({ length: n }, (_, i) => {
    const t = i / SR;
    return Math.sin(2 * Math.PI * 60 * t) + 0.5 * Math.sin(2 * Math.PI * 120 * t) + 0.3 * Math.sin(2 * Math.PI * 180 * t);
  });
}

function addNoise(s: Float32Array, n: Float32Array, snrDb: number): { x: Float32Array; noise: Float32Array } {
  // 잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다
  const nn = n.subarray(0, s.length);
  const g = Math.sqrt(power(s) / (power(nn) * 10 ** (snrDb / 10)));
  const noise = nn.map((v) => g * v);
  return { x: s.map((v, i) => v + noise[i]), noise };
}

function snrVs(ref: ArrayLike<number>, est: ArrayLike<number>): number {
  // 깨끗한 원본 대비 남은 오차로 잰 SNR (dB)
  let a = 0;
  let b = 0;
  for (let i = 0; i < ref.length; i++) {
    a += ref[i] * ref[i];
    b += (ref[i] - est[i]) ** 2;
  }
  return 10 * Math.log10(a / b);
}


const NOISES: Record<string, Float32Array> = { white: whiteNoise(clean.length), pink: pinkNoise(clean.length), hum: humNoise(clean.length) };

// 빈칸 실습 1의 답: g = sqrt(P_s / (P_n x 10^(SNR/10))) 로 잡음 크기를 맞춘다
let ok = true;
for (const snr of [20, 10, 0]) {
  const { noise } = addNoise(clean, NOISES.white, snr);
  const measured = 10 * Math.log10(power(clean) / power(noise));
  ok = ok && Math.abs(measured - snr) < 0.01;
  console.log(`목표 ${String(snr).padStart(3)} dB -> 측정 ${measured.toFixed(2).padStart(6)} dB`);
}
check(ok, "목표 SNR과 측정 SNR이 같아야 해요.");

// 수식 검증 1: dB <-> 파워 비 / 진폭 비
for (const d of [30, 20, 10, 6, 3, 0, -10]) console.log(`${String(d).padStart(4)} dB -> 파워 비 ${(10 ** (d / 10)).toFixed(3).padStart(9)} | 진폭 비 ${(10 ** (d / 20)).toFixed(3).padStart(7)}`);

// 잡음 종류별 스펙트럼: 1024칸씩 잘라 평균 파워를 내고 500 Hz 아래에 얼마나 몰려 있나
const low: Record<string, number> = {};
let humPeak = 0;
for (const [name, n] of Object.entries(NOISES)) {
  const avg = new Float64Array(513);
  const w = hann(1024);
  for (let s = 0; s + 1024 <= n.length; s += 512) magnitude(n.subarray(s, s + 1024), 1024, w).forEach((v, k) => (avg[k] += v * v));
  const total = avg.reduce((a, v) => a + v, 0);
  low[name] = avg.slice(0, Math.floor((500 * 1024) / SR)).reduce((a, v) => a + v, 0) / total;
  const peak = avg.indexOf(Math.max(...avg));
  if (name === "hum") humPeak = (peak * SR) / 1024;
  console.log(`${name.padEnd(5)}: 500 Hz 아래 파워 ${(low[name] * 100).toFixed(1)}%, 가장 센 주파수 ${((peak * SR) / 1024).toFixed(0)} Hz`);
}
check(low.pink > low.white * 3 && Math.abs(humPeak - 60) < 16, "핑크는 낮은 쪽에 몰리고 험은 60 Hz가 가장 세요.");

