  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
