}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답


const dbfsPeak = (x: Float32Array): number => 20 * Math.log10(x.reduce((a, v) => Math.max(a, Math.abs(v)), 0) + 1e-12);
const dbfsRms = (x: Float32Array): number => 10 * Math.log10(power(x) + 1e-24);

function peakNormalize(x: Float32Array, peak: number = 0.9): Float32Array {
  const p = x.reduce((a, v) => Math.max(a, Math.abs(v)), 1e-12);
  return x.map((v) => (v * peak) / p);
}

// 빈칸 실습 2의 답: dB 차이를 진폭 비로 바꿀 때는 20으로 나눈다
function rmsNormalize(x: Float32Array, targetDb: number = -20, peakLimit: number = 0.99): Float32Array {
  const mean = x.reduce((a, v) => a + v, 0) / x.length;
  const c = x.map((v) => v - mean); // DC 제거
  const gain = 10 ** ((targetDb - dbfsRms(c)) / 20); // dB 차이 -> 진폭 비
  const y = c.map((v) => v * gain);
  const peak = y.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  return peak > peakLimit ? y.map((v) => (v * peakLimit) / peak) : y; // 클리핑 방지
}

const quiet = clean.map((v) => 0.1 * v);
const clicky = quiet.slice();
clicky[Math.round(1.5 * SR)] = 0.95; // 순간 클릭 하나
const dc = quiet.map((v) => v + 0.2); // DC offset 0.2
const res: Record<string, { rms: number; peak: number; mean: number }> = {};
console.log("               원래 RMS  peak 정규화 RMS  RMS 정규화 RMS    peak");
for (const [name, x] of [["작은 음성", quiet], ["클릭 하나 포함", clicky], ["DC offset 0.2", dc]] as Array<[string, Float32Array]>) {
  const y = rmsNormalize(x);
  res[name] = { rms: dbfsRms(y), peak: dbfsPeak(y), mean: y.reduce((a, v) => a + v, 0) / y.length };
  console.log(`${name.padEnd(12)} ${dbfsRms(x).toFixed(1).padStart(8)} ${dbfsRms(peakNormalize(x)).toFixed(1).padStart(15)} ${res[name].rms.toFixed(1).padStart(15)} ${res[name].peak.toFixed(1).padStart(7)}`);
}
console.log("클릭 하나 때문에 peak 정규화는 말소리를 작게 만든다:", dbfsRms(peakNormalize(clicky)).toFixed(1), "dBFS (RMS 정규화는 -20 목표)");

check(Math.abs(res["작은 음성"].rms + 20) < 0.1 && Math.abs(res["DC offset 0.2"].rms + 20) < 0.1 && Math.abs(res["DC offset 0.2"].mean) < 1e-5, "작은 음성 · DC offset은 RMS -20 dBFS, 평균 0이 돼야 해요.");
check(res["클릭 하나 포함"].peak <= 20 * Math.log10(0.99) + 1e-3 && res["클릭 하나 포함"].rms < -20, "클릭이 있으면 peak 제한 때문에 RMS가 -20보다 낮게 남아요.");
check(Math.abs(10 ** (13 / 20) - 4.47) < 0.01, "-33 dBFS를 -20 dBFS로: 10^(13/20) = 4.47배 입니다.");

