  const pred = Math.sqrt(1 + alpha ** 2 - 2 * alpha * Math.cos(w));
  const x = tone(f, 0.5, SR, 0.5);
  const meas = Math.sqrt(power(preemphasis(x, alpha).subarray(100))) / Math.sqrt(power(x.subarray(100)));
  ok = ok && Math.abs(meas - pred) < 0.01;
  console.log(`${String(f).padStart(5)} Hz: 예측 |H| ${pred.toFixed(3)} (${(20 * Math.log10(pred)).toFixed(1).padStart(6)} dB) | 측정 ${meas.toFixed(3)}`);
}
check(ok, "예측한 응답과 측정이 같아야 해요.");

function highpass(x: Float32Array, fc: number): Float32Array {
  // 2차 high-pass(RBJ biquad, Q = 0.707)를 앞으로 한 번, 뒤로 한 번 지나게 함(zero-phase = filtfilt) → 소리가 밀리지 않고 기울기는 4차
  const w0 = (2 * Math.PI * fc) / SR;
  const alphaQ = Math.sin(w0) / (2 * Math.SQRT1_2);
  const c = Math.cos(w0);
  const a0 = 1 + alphaQ;
  const [b0, b1, b2] = [(1 + c) / 2 / a0, -(1 + c) / a0, (1 + c) / 2 / a0];
  const [a1, a2] = [(-2 * c) / a0, (1 - alphaQ) / a0];
  const once = (y: Float64Array): Float64Array => {
    const out = new Float64Array(y.length);
    let [x1, x2, y1, y2] = [0, 0, 0, 0];
    for (let i = 0; i < y.length; i++) {
      out[i] = b0 * y[i] + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2;
      [x2, x1, y2, y1] = [x1, y[i], y1, out[i]];
    }
    return out;
  };
  return Float32Array.from(once(once(Float64Array.from(x)).reverse()).reverse());
}

// high-pass 필터: 험(60 Hz)을 0 dB로 섞고 100 Hz 필터로 걷어 낸다
const { x: hummy } = addNoise(clean, humNoise(clean.length), 0);
const yHp = highpass(hummy, 100);
const before = snrVs(clean, hummy);
const after = snrVs(clean, yHp);
console.log(`험 섞인 음성 SNR ${before.toFixed(1)} dB -> high-pass 후 ${after.toFixed(1)} dB`);
check(after > before + 4, "high-pass 후 SNR이 크게 올라가야 해요.");

specsub.python:
# D4 · Part 3 · 노이즈 제거 1: 스펙트럼 차감과 Wiener 이득 — 단독 실행 완성 코드 (Python 3.11)
# pip install librosa==0.11.0 numpy==2.4.6
# 실행: python d04_specsub.py   (입력 소리는 코드 안에서 합성해요 · 인터넷·GPU·마이크 불필요)
#   앞 0.5초 무음으로 잡음 파워를 추정해 스펙트럼 차감 · Wiener 이득으로 SNR을 올리고, 추정 구간이 길면 왜 나빠지는지 확인
import librosa
import numpy as np

SR = 16000                                   # 음성 모델 표준: 1초에 16,000번 측정 (16kHz)


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def synth_voice(seconds: float = 2.0, f0: float = 140.0, seed: int = 0, sr: int = SR) -> np.ndarray:
    """말소리 비슷한 합성 신호(mono float32): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음."""
    rng = np.random.default_rng(seed)
    t = np.arange(int(seconds * sr)) / sr
    pitch = f0 * (1 + 0.05 * np.sin(2 * np.pi * 0.7 * t))              # 억양처럼 천천히 오르내림
    phase = 2 * np.pi * np.cumsum(pitch) / sr
    y = sum(np.sin(k * phase) / k for k in range(1, 6))                 # 배음 5개
    env = np.clip(np.sin(2 * np.pi * 2.5 * t), 0, None) ** 0.5           # 1초에 음절 5개쯤
    y = y * env + 0.01 * rng.standard_normal(len(t))
    return (0.8 * y / max(float(np.abs(y).max()), 1e-9)).astype(np.float32)


def make_clean() -> np.ndarray:
    """앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)."""
    voice = 0.3 * synth_voice(1.8)
    return np.concatenate([np.zeros(int(0.8 * SR)), voice, np.zeros(int(0.5 * SR))]).astype(np.float32)


clean = make_clean()
SPEECH = (0.8, 2.6)                                            # 말소리가 있는 구간(초) = 정답

rng = np.random.default_rng(0)


def power(x: np.ndarray) -> float:
    return float(np.mean(x ** 2))


def white_noise(n: int) -> np.ndarray:
    return rng.standard_normal(n).astype(np.float32)


def pink_noise(n: int) -> np.ndarray:
    """1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (팬, 바람에 가까움)."""
    X = np.fft.rfft(rng.standard_normal(n))
    f = np.arange(len(X))
    f[0] = 1
    return np.fft.irfft(X / np.sqrt(f), n).astype(np.float32)


def hum_noise(n: int) -> np.ndarray:
    """전원 험: 60 Hz와 배음 120 · 180 Hz."""
    t = np.arange(n) / SR
    return sum(a * np.sin(2 * np.pi * f * t) for f, a in ((60, 1.0), (120, 0.5), (180, 0.3))).astype(np.float32)


def add_noise(s: np.ndarray, n: np.ndarray, snr_db: float):
    """잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다 -> (섞은 소리, 실제로 더한 잡음)."""
    n = n[:len(s)]
    g = np.sqrt(power(s) / (power(n) * 10 ** (snr_db / 10)))
    return (s + g * n).astype(np.float32), (g * n).astype(np.float32)


def snr_vs(ref: np.ndarray, est: np.ndarray) -> float:
    """깨끗한 원본 대비 남은 오차로 잰 SNR (dB)."""
    return float(10 * np.log10(np.sum(ref ** 2) / np.sum((ref - est) ** 2)))


N_FFT, HOP = 512, 128
noisy, _ = add_noise(clean, white_noise(len(clean)), 5)         # 백색 잡음 5 dB


def noise_psd(Y: np.ndarray, noise_sec: float = 0.5) -> np.ndarray:
    """앞쪽 noise_sec초 프레임의 평균 파워 = 잡음 추정, 모양 (칸 수, 1)."""
    M0 = int(noise_sec * SR / HOP)
    return np.mean(np.abs(Y[:, :M0]) ** 2, axis=1, keepdims=True)


# 빈칸 실습 4의 답: P - beta x N, 바닥은 원래 파워의 2%
def spectral_subtract(x: np.ndarray, beta: float = 2.0, floor: float = 0.02, noise_sec: float = 0.5) -> np.ndarray:
    Y = librosa.stft(x, n_fft=N_FFT, hop_length=HOP)
    P = np.abs(Y) ** 2
    S_pow = np.maximum(P - beta * noise_psd(Y, noise_sec), floor * P)
    S_hat = np.sqrt(S_pow) * np.exp(1j * np.angle(Y))           # 크기는 새로, 위상은 noisy 그대로
    return librosa.istft(S_hat, hop_length=HOP, length=len(x)).astype(np.float32)


# 빈칸 실습 5의 답: G = xi / (1 + xi)
def wiener(x: np.ndarray, noise_sec: float = 0.5) -> np.ndarray:
    Y = librosa.stft(x, n_fft=N_FFT, hop_length=HOP)
    xi = np.maximum(np.abs(Y) ** 2 / noise_psd(Y, noise_sec) - 1, 0)    # 칸마다의 SNR 추정
    G = xi / (1 + xi)                                                   # Wiener 이득 (0 ~ 1)
    return librosa.istft(G * Y, hop_length=HOP, length=len(x)).astype(np.float32)


base = snr_vs(clean, noisy)
for b in (1, 2, 4):
    print(f"스펙트럼 차감 beta={b}: SNR {base:5.2f} -> {snr_vs(clean, spectral_subtract(noisy, beta=b)):5.2f} dB")
ss_snr, w_snr = snr_vs(clean, spectral_subtract(noisy)), snr_vs(clean, wiener(noisy))
print(f"Wiener: SNR {base:5.2f} -> {w_snr:5.2f} dB")
check(ss_snr > base + 1.5 and w_snr > base + 1.5, "스펙트럼 차감과 Wiener 모두 SNR을 올려야 해요.")

# 수식 검증 3: Wiener 이득 값, 그리고 잡음 추정 구간이 말소리까지 들어가면 나빠진다
for xi_db in (-10, 0, 10, 20):
    xi = 10 ** (xi_db / 10)
    print(f"칸 SNR {xi_db:+3d} dB -> G = {xi / (1 + xi):.3f}")
res = {}
for ns in (0.1, 0.5, 0.8, 2.0):
    res[ns] = snr_vs(clean, spectral_subtract(noisy, beta=2, noise_sec=ns))
    print(f"잡음 추정 구간 {ns:.1f}초 -> SNR {res[ns]:5.2f} dB" + ("   <- 말소리까지 '잡음'으로 평균됨" if ns > 0.8 else ""))
check(res[0.5] > res[2.0], "말소리가 섞인 2.0초로 잡음을 추정하면 0.5초보다 나빠야 해요.")

specsub.typescript:
// D4 · Part 3 · 노이즈 제거 1: 스펙트럼 차감과 Wiener 이득 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d04_specsub.ts
//   앞 0.5초 무음으로 잡음 파워를 추정해 스펙트럼 차감 · Wiener 이득으로 SNR을 올리고, 추정 구간이 길면 왜 나빠지는지 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
  return out;
}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답

const rnd = mulberry32(0);

function whiteNoise(n: number): Float32Array {
  return Float32Array.from({ length: n }, () => gauss(rnd));
}

function pinkNoise(n: number): Float32Array {
  // 1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (Paul Kellet의 간단한 필터)
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  return Float32Array.from({ length: n }, () => {
    const w = gauss(rnd);
    b0 = 0.99765 * b0 + w * 0.099046;
    b1 = 0.963 * b1 + w * 0.2965164;
    b2 = 0.57 * b2 + w * 1.0526913;
    return b0 + b1 + b2 + w * 0.1848;
  });
}

function humNoise(n: number): Float32Array {
  // 전원 험: 60 Hz와 배음 120 · 180 Hz
  return Float32Array.from({ length: n }, (_, i) => {
    const t = i / SR;
    return Math.sin(2 * Math.PI * 60 * t) + 0.5 * Math.sin(2 * Math.PI * 120 * t) + 0.3 * Math.sin(2 * Math.PI * 180 * t);
  });
}

function addNoise(s: Float32Array, n: Float32Array, snrDb: number): { x: Float32Array; noise: Float32Array } {
  // 잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다
  const nn = n.subarray(0, s.length);
  const g = Math.sqrt(power(s) / (power(nn) * 10 ** (snrDb / 10)));
  const noise = nn.map((v) => g * v);
  return { x: s.map((v, i) => v + noise[i]), noise };
}

function snrVs(ref: ArrayLike<number>, est: ArrayLike<number>): number {
  // 깨끗한 원본 대비 남은 오차로 잰 SNR (dB)
  let a = 0;
  let b = 0;
  for (let i = 0; i < ref.length; i++) {
    a += ref[i] * ref[i];
    b += (ref[i] - est[i]) ** 2;
  }
  return 10 * Math.log10(a / b);
}

const N_FFT = 512;
const HOP = 128;
const HANN = Float64Array.from({ length: N_FFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / N_FFT)); // 주기형 Hann

interface Spec {
  re: Float64Array[]; // [프레임][칸]
  im: Float64Array[];
}

function stft(y: Float32Array): Spec {
  // 앞뒤로 N_FFT만큼 0을 붙여 모든 샘플이 같은 횟수 겹치게 한 STFT (칸 수 N_FFT/2 + 1)
  const pad = new Float32Array(y.length + 2 * N_FFT);
  pad.set(y, N_FFT);
  const spec: Spec = { re: [], im: [] };
  for (let s = 0; s + N_FFT <= pad.length; s += HOP) {
    const re = new Float64Array(N_FFT);
    const im = new Float64Array(N_FFT);
    for (let i = 0; i < N_FFT; i++) re[i] = pad[s + i] * HANN[i];
    fft(re, im);
    spec.re.push(re.slice(0, N_FFT / 2 + 1));
    spec.im.push(im.slice(0, N_FFT / 2 + 1));
  }
  return spec;
}

function istft(spec: Spec, length: number): Float32Array {
  // 역변환 + 겹쳐 더하기(overlap-add): 켤레 대칭으로 전체 칸을 채우고 역FFT = conj(FFT(conj X)) / N
  const total = (spec.re.length - 1) * HOP + N_FFT;
  const acc = new Float64Array(total);
  const wsum = new Float64Array(total);
  spec.re.forEach((r, m) => {
    const re = new Float64Array(N_FFT);
    const im = new Float64Array(N_FFT);
    for (let k = 0; k < N_FFT; k++) {
      const kk = k <= N_FFT / 2 ? k : N_FFT - k;
      re[k] = r[kk];
      im[k] = (k <= N_FFT / 2 ? -1 : 1) * spec.im[m][kk]; // conj
    }
    fft(re, im);
    for (let i = 0; i < N_FFT; i++) {
      acc[m * HOP + i] += (re[i] / N_FFT) * HANN[i];
      wsum[m * HOP + i] += HANN[i] * HANN[i];
    }
  });
  return Float32Array.from({ length }, (_, i) => acc[N_FFT + i] / Math.max(wsum[N_FFT + i], 1e-8));
}

function noisePsd(spec: Spec, noiseSec: number = 0.5): Float64Array {
  // 앞쪽 noiseSec초 프레임의 평균 파워 = 잡음 추정 (패딩한 N_FFT만큼 건너뜀)
  const m0 = Math.floor((noiseSec * SR) / HOP);
  const first = Math.floor(N_FFT / HOP);
  const out = new Float64Array(N_FFT / 2 + 1);
  for (let m = first; m < first + m0; m++) for (let k = 0; k < out.length; k++) out[k] += (spec.re[m][k] ** 2 + spec.im[m][k] ** 2) / m0;
  return out;
}


const noisy = addNoise(clean, whiteNoise(clean.length), 5).x; // 백색 잡음 5 dB

// 빈칸 실습 4의 답: P - beta x N, 바닥은 원래 파워의 2%
function spectralSubtract(x: Float32Array, beta: number = 2, floor: number = 0.02, noiseSec: number = 0.5): Float32Array {
  const spec = stft(x);
  const nhat = noisePsd(spec, noiseSec);
  spec.re.forEach((r, m) =>
    r.forEach((_, k) => {
      const p = r[k] ** 2 + spec.im[m][k] ** 2;
      const g = Math.sqrt(Math.max(p - beta * nhat[k], floor * p) / Math.max(p, 1e-20)); // 크기는 새로, 위상은 그대로
      r[k] *= g;
      spec.im[m][k] *= g;
    }),
  );
  return istft(spec, x.length);
}

// 빈칸 실습 5의 답: G = xi / (1 + xi)
function wiener(x: Float32Array, noiseSec: number = 0.5): Float32Array {
  const spec = stft(x);
  const nhat = noisePsd(spec, noiseSec);
  spec.re.forEach((r, m) =>
    r.forEach((_, k) => {
      const xi = Math.max((r[k] ** 2 + spec.im[m][k] ** 2) / nhat[k] - 1, 0); // 칸마다의 SNR 추정
      const g = xi / (1 + xi); // Wiener 이득 (0 ~ 1)
      r[k] *= g;
      spec.im[m][k] *= g;
    }),
  );
  return istft(spec, x.length);
}

const base = snrVs(clean, noisy);
for (const b of [1, 2, 4]) console.log(`스펙트럼 차감 beta=${b}: SNR ${base.toFixed(2)} -> ${snrVs(clean, spectralSubtract(noisy, b)).toFixed(2)} dB`);
const ssSnr = snrVs(clean, spectralSubtract(noisy));
const wSnr = snrVs(clean, wiener(noisy));
console.log(`Wiener: SNR ${base.toFixed(2)} -> ${wSnr.toFixed(2)} dB`);
check(ssSnr > base + 1.5 && wSnr > base + 1.5, "스펙트럼 차감과 Wiener 모두 SNR을 올려야 해요.");

// 수식 검증 3: Wiener 이득 값, 그리고 잡음 추정 구간이 말소리까지 들어가면 나빠진다
for (const db of [-10, 0, 10, 20]) {
  const xi = 10 ** (db / 10);
  console.log(`칸 SNR ${db >= 0 ? "+" : ""}${db} dB -> G = ${(xi / (1 + xi)).toFixed(3)}`);
}
const res: Record<number, number> = {};
for (const ns of [0.1, 0.5, 0.8, 2.0]) {
  res[ns] = snrVs(clean, spectralSubtract(noisy, 2, 0.02, ns));
  console.log(`잡음 추정 구간 ${ns.toFixed(1)}초 -> SNR ${res[ns].toFixed(2)} dB${ns > 0.8 ? "   <- 말소리까지 '잡음'으로 평균됨" : ""}`);
}
check(res[0.5] > res[2.0], "말소리가 섞인 2.0초로 잡음을 추정하면 0.5초보다 나빠야 해요.");

gate.typescript:
// D4 · Part 4 · 노이즈 제거 2: spectral gating (noisereduce) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d04_gate.ts
//   스펙트럼 gating: 잡음 구간의 칸별 평균 μ · 표준편차 σ 로 문턱 μ + n_std·σ 를 만들어 못 넘는 칸을 줄이기
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
  return out;
}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답

const rnd = mulberry32(0);

function whiteNoise(n: number): Float32Array {
  return Float32Array.from({ length: n }, () => gauss(rnd));
}

function pinkNoise(n: number): Float32Array {
  // 1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (Paul Kellet의 간단한 필터)
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  return Float32Array.from({ length: n }, () => {
    const w = gauss(rnd);
    b0 = 0.99765 * b0 + w * 0.099046;
    b1 = 0.963 * b1 + w * 0.2965164;
    b2 = 0.57 * b2 + w * 1.0526913;
    return b0 + b1 + b2 + w * 0.1848;
  });
}

function humNoise(n: number): Float32Array {
  // 전원 험: 60 Hz와 배음 120 · 180 Hz
  return Float32Array.from({ length: n }, (_, i) => {
    const t = i / SR;
    return Math.sin(2 * Math.PI * 60 * t) + 0.5 * Math.sin(2 * Math.PI * 120 * t) + 0.3 * Math.sin(2 * Math.PI * 180 * t);
  });
}

function addNoise(s: Float32Array, n: Float32Array, snrDb: number): { x: Float32Array; noise: Float32Array } {
  // 잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다
  const nn = n.subarray(0, s.length);
  const g = Math.sqrt(power(s) / (power(nn) * 10 ** (snrDb / 10)));
  const noise = nn.map((v) => g * v);
  return { x: s.map((v, i) => v + noise[i]), noise };
}

function snrVs(ref: ArrayLike<number>, est: ArrayLike<number>): number {
  // 깨끗한 원본 대비 남은 오차로 잰 SNR (dB)
  let a = 0;
  let b = 0;
  for (let i = 0; i < ref.length; i++) {
    a += ref[i] * ref[i];
    b += (ref[i] - est[i]) ** 2;
  }
  return 10 * Math.log10(a / b);
}

const N_FFT = 512;
const HOP = 128;
const HANN = Float64Array.from({ length: N_FFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / N_FFT)); // 주기형 Hann

interface Spec {
  re: Float64Array[]; // [프레임][칸]
  im: Float64Array[];
}

function stft(y: Float32Array): Spec {
  // 앞뒤로 N_FFT만큼 0을 붙여 모든 샘플이 같은 횟수 겹치게 한 STFT (칸 수 N_FFT/2 + 1)
  const pad = new Float32Array(y.length + 2 * N_FFT);
  pad.set(y, N_FFT);
  const spec: Spec = { re: [], im: [] };
  for (let s = 0; s + N_FFT <= pad.length; s += HOP) {
    const re = new Float64Array(N_FFT);
    const im = new Float64Array(N_FFT);
    for (let i = 0; i < N_FFT; i++) re[i] = pad[s + i] * HANN[i];
    fft(re, im);
    spec.re.push(re.slice(0, N_FFT / 2 + 1));
    spec.im.push(im.slice(0, N_FFT / 2 + 1));
  }
  return spec;
}

function istft(spec: Spec, length: number): Float32Array {
  // 역변환 + 겹쳐 더하기(overlap-add): 켤레 대칭으로 전체 칸을 채우고 역FFT = conj(FFT(conj X)) / N
  const total = (spec.re.length - 1) * HOP + N_FFT;
  const acc = new Float64Array(total);
  const wsum = new Float64Array(total);
  spec.re.forEach((r, m) => {
    const re = new Float64Array(N_FFT);
    const im = new Float64Array(N_FFT);
    for (let k = 0; k < N_FFT; k++) {
      const kk = k <= N_FFT / 2 ? k : N_FFT - k;
      re[k] = r[kk];
      im[k] = (k <= N_FFT / 2 ? -1 : 1) * spec.im[m][kk]; // conj
    }
    fft(re, im);
    for (let i = 0; i < N_FFT; i++) {
      acc[m * HOP + i] += (re[i] / N_FFT) * HANN[i];
      wsum[m * HOP + i] += HANN[i] * HANN[i];
    }
  });
  return Float32Array.from({ length }, (_, i) => acc[N_FFT + i] / Math.max(wsum[N_FFT + i], 1e-8));
}

function noisePsd(spec: Spec, noiseSec: number = 0.5): Float64Array {
  // 앞쪽 noiseSec초 프레임의 평균 파워 = 잡음 추정 (패딩한 N_FFT만큼 건너뜀)
  const m0 = Math.floor((noiseSec * SR) / HOP);
  const first = Math.floor(N_FFT / HOP);
  const out = new Float64Array(N_FFT / 2 + 1);
  for (let m = first; m < first + m0; m++) for (let k = 0; k < out.length; k++) out[k] += (spec.re[m][k] ** 2 + spec.im[m][k] ** 2) / m0;
  return out;
}


const noisy = addNoise(clean, whiteNoise(clean.length), 5).x; // 백색 잡음 5 dB
const sil = [0, Math.round(0.7 * SR)];
const sp = [Math.round(0.8 * SR), clean.length - Math.round(0.5 * SR)];

function gate(x: Float32Array, nStd: number, noiseSec: number = 0.5, atten: number = 0.05): { out: Float32Array; pass: number[][] } {
  // 잡음 구간의 칸별 dB 평균 mu · 표준편차 sd 로 문턱 T = mu + nStd x sd 를 만들고, 못 넘는 칸은 atten(약 -26 dB)배로 줄인다
  const spec = stft(x);
  const first = Math.floor(N_FFT / HOP);
  const m0 = Math.floor((noiseSec * SR) / HOP);
  const db = spec.re.map((r, m) => Float64Array.from(r, (_, k) => 10 * Math.log10(r[k] ** 2 + spec.im[m][k] ** 2 + 1e-20)));
  const K = N_FFT / 2 + 1;
  const mu = new Float64Array(K);
  const sd = new Float64Array(K);
  for (let k = 0; k < K; k++) {
    for (let m = first; m < first + m0; m++) mu[k] += db[m][k] / m0;
    for (let m = first; m < first + m0; m++) sd[k] += (db[m][k] - mu[k]) ** 2 / m0;
    sd[k] = Math.sqrt(sd[k]);
  }
  const pass = db.map((row) => Array.from(row, (v, k) => (v > mu[k] + nStd * sd[k] ? 1 : 0)));
  spec.re.forEach((r, m) =>
    r.forEach((_, k) => {
      const g = pass[m][k] ? 1 : atten;
      r[k] *= g;
      spec.im[m][k] *= g;
    }),
  );
  return { out: istft(spec, x.length), pass };
}

function report(name: string, out: Float32Array): { drop: number; keep: number } {
  // 무음 구간 잡음 감소량(dB)과 말소리 구간 크기 변화(dB)
  const drop = 10 * Math.log10(power(noisy.subarray(sil[0], sil[1])) / (power(out.subarray(sil[0], sil[1])) + 1e-12));
  const keep = 10 * Math.log10(power(out.subarray(sp[0], sp[1])) / power(noisy.subarray(sp[0], sp[1])));
  console.log(`${name.padEnd(24)} SNR ${snrVs(clean, out).toFixed(2).padStart(6)} dB | 무음 구간 잡음 감소 ${drop.toFixed(1).padStart(5)} dB | 말소리 구간 크기 ${keep >= 0 ? "+" : ""}${keep.toFixed(1)} dB`);
  return { drop, keep };
}

report("잡음 섞인 음성 (그대로)", noisy);
const r15 = report("gating n_std=1.5", gate(noisy, 1.5).out);
check(r15.drop > 6 && r15.keep > -3, "무음 구간 잡음은 크게 줄고 말소리는 거의 그대로 남아야 해요.");

// 수식 검증 4: 문턱 T = mu + n_std x sigma 를 높일수록 통과하는 칸이 줄어든다
const rates: number[][] = [];
for (const nStd of [0.5, 1.5, 3]) {
  const { pass } = gate(noisy, nStd);
  const frac = (from: number, to: number): number => {
    let c = 0;
    let n = 0;
    for (let m = from; m < to; m++) pass[m].forEach((v) => ((c += v), n++));
    return c / n;
  };
  const silFrac = frac(8, 8 + 50); // 무음 구간 프레임들
  const spFrac = frac(8 + 120, 8 + 250); // 말소리 구간 프레임들
  rates.push([silFrac, spFrac]);
  console.log(`n_std=${nStd}: 통과한 칸 비율 - 무음 구간 ${(silFrac * 100).toFixed(1)}% | 말소리 구간 ${(spFrac * 100).toFixed(1)}%`);
}
console.log("-> 문턱을 높일수록 잡음은 덜 통과하지만, 약한 말소리 칸도 같이 막힙니다.");
check(rates[0][0] > rates[1][0] && rates[1][0] > rates[2][0] && rates[0][1] >= rates[2][1] && rates[1][1] > rates[1][0], "문턱이 높을수록 덜 통과하고, 말소리 칸이 무음 칸보다 더 통과해야 해요.");

vad.python:
# D4 · Part 5 · VAD 1: 에너지와 ZCR로 말소리 구간 찾기 — 단독 실행 완성 코드 (Python 3.11)
# pip install librosa==0.11.0 numpy==2.4.6
# 실행: python d04_vad.py   (입력 소리는 코드 안에서 합성해요 · 인터넷·GPU·마이크 불필요)
#   프레임 에너지(dB) 문턱 2개(hysteresis) + hangover 로 말소리 구간을 찾고, ZCR ≈ 2f/fs 확인, 잡음이 커질 때 정확도 변화
import librosa
import numpy as np

SR = 16000                                   # 음성 모델 표준: 1초에 16,000번 측정 (16kHz)


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def tone(freq: float, sec: float = 1.0, sr: int = SR, amp: float = 0.5, phase: float = 0.0) -> np.ndarray:
    """freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi) 를 숫자 배열로 만든다."""
    t = np.arange(int(sr * sec)) / sr
    return (amp * np.sin(2 * np.pi * freq * t + phase)).astype(np.float32)


def synth_voice(seconds: float = 2.0, f0: float = 140.0, seed: int = 0, sr: int = SR) -> np.ndarray:
    """말소리 비슷한 합성 신호(mono float32): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음."""
    rng = np.random.default_rng(seed)
    t = np.arange(int(seconds * sr)) / sr
    pitch = f0 * (1 + 0.05 * np.sin(2 * np.pi * 0.7 * t))              # 억양처럼 천천히 오르내림
    phase = 2 * np.pi * np.cumsum(pitch) / sr
    y = sum(np.sin(k * phase) / k for k in range(1, 6))                 # 배음 5개
    env = np.clip(np.sin(2 * np.pi * 2.5 * t), 0, None) ** 0.5           # 1초에 음절 5개쯤
    y = y * env + 0.01 * rng.standard_normal(len(t))
    return (0.8 * y / max(float(np.abs(y).max()), 1e-9)).astype(np.float32)


def make_clean() -> np.ndarray:
    """앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)."""
    voice = 0.3 * synth_voice(1.8)
    return np.concatenate([np.zeros(int(0.8 * SR)), voice, np.zeros(int(0.5 * SR))]).astype(np.float32)


clean = make_clean()
SPEECH = (0.8, 2.6)                                            # 말소리가 있는 구간(초) = 정답

rng = np.random.default_rng(0)


def power(x: np.ndarray) -> float:
    return float(np.mean(x ** 2))


def white_noise(n: int) -> np.ndarray:
    return rng.standard_normal(n).astype(np.float32)


def pink_noise(n: int) -> np.ndarray:
    """1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (팬, 바람에 가까움)."""
    X = np.fft.rfft(rng.standard_normal(n))
    f = np.arange(len(X))
    f[0] = 1
    return np.fft.irfft(X / np.sqrt(f), n).astype(np.float32)


def hum_noise(n: int) -> np.ndarray:
    """전원 험: 60 Hz와 배음 120 · 180 Hz."""
    t = np.arange(n) / SR
    return sum(a * np.sin(2 * np.pi * f * t) for f, a in ((60, 1.0), (120, 0.5), (180, 0.3))).astype(np.float32)


def add_noise(s: np.ndarray, n: np.ndarray, snr_db: float):
    """잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다 -> (섞은 소리, 실제로 더한 잡음)."""
    n = n[:len(s)]
    g = np.sqrt(power(s) / (power(n) * 10 ** (snr_db / 10)))
    return (s + g * n).astype(np.float32), (g * n).astype(np.float32)


def snr_vs(ref: np.ndarray, est: np.ndarray) -> float:
    """깨끗한 원본 대비 남은 오차로 잰 SNR (dB)."""
    return float(10 * np.log10(np.sum(ref ** 2) / np.sum((ref - est) ** 2)))

def frame_mask(segs, total_sec: float, hop_sec: float = 0.01) -> np.ndarray:
    """(시작 초, 끝 초) 구간 목록 -> 10 ms 프레임마다 말소리면 True."""
    m = np.zeros(int(total_sec / hop_sec) + 1, bool)
    for a, b in segs:
        m[int(a / hop_sec):int(b / hop_sec)] = True
    return m



# 빈칸 실습 7의 답: 에너지(dB) = 20 log10(RMS). 켤 때(T_hi) 더 높고 끌 때(T_lo) 더 낮은 문턱 + hangover
def energy_vad(x: np.ndarray, hi_db: float = 12, lo_db: float = 6, hang_sec: float = 0.3, min_speech_sec: float = 0.25, hop: int = 160):
    rms = librosa.feature.rms(y=x, frame_length=400, hop_length=hop)[0]
    e = 20 * np.log10(rms + 1e-10)                         # 프레임 에너지 (dB)
    floor = np.percentile(e, 10)                           # 잡음 바닥
    T_hi, T_lo = floor + hi_db, floor + lo_db
    hang = int(hang_sec * SR / hop)                        # hangover 프레임 수
    segs, speaking, quiet, start = [], False, 0, 0
    for m, v in enumerate(e):
        if not speaking:
            if v > T_hi:
                speaking, start, quiet = True, m, 0
        elif v > T_lo:
            quiet = 0
        else:
            quiet += 1
            if quiet > hang:
                segs.append((start, m - quiet))
                speaking = False
    if speaking:
        segs.append((start, len(e) - 1 - quiet))
    return [(a * hop / SR, (b + 1) * hop / SR) for a, b in segs if (b - a + 1) * hop / SR >= min_speech_sec]


segs = energy_vad(clean)
print("에너지 VAD 구간:", [(round(a, 2), round(b, 2)) for a, b in segs], "| 정답", SPEECH)
check(len(segs) == 1 and abs(segs[0][0] - SPEECH[0]) < 0.15 and abs(segs[0][1] - SPEECH[1]) < 0.3, "말소리 구간 하나를 0.3초 안으로 찾아야 해요.")

# 수식 검증 5: ZCR = 2f / fs, 백색 잡음은 약 0.5
ok = True
for f in (150, 1000, 3000):
    z = librosa.feature.zero_crossing_rate(tone(f), frame_length=400, hop_length=160)[0].mean()
    ok &= abs(z - 2 * f / SR) < 0.005
    print(f"{f:5d} Hz 사인파: ZCR {z:.4f} | 예측 2f/fs = {2 * f / SR:.4f}")
zw = librosa.feature.zero_crossing_rate(white_noise(SR))[0].mean()
print(f"백색잡음 ZCR: {zw:.3f} (약 0.5)")
check(ok and abs(zw - 0.5) < 0.05, "ZCR은 2f/fs, 백색 잡음은 약 0.5 입니다.")

# 잡음이 커지면 에너지 VAD 정확도는? (10 ms 프레임 일치율)
ref = frame_mask([SPEECH], len(clean) / SR)
acc = {}
for snr in (20, 10, 5, 0):
    x, _ = add_noise(clean, white_noise(len(clean)), snr)
    acc[snr] = float((frame_mask(energy_vad(x), len(clean) / SR) == ref).mean())
    print(f"SNR {snr:2d} dB: 에너지 VAD 일치율 {acc[snr]:.1%}")
check(acc[20] > 0.9, "깨끗할 때는 90% 이상 일치해야 해요.")

vad.typescript:
// D4 · Part 5 · VAD 1: 에너지와 ZCR로 말소리 구간 찾기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d04_vad.ts
//   프레임 에너지(dB) 문턱 2개(hysteresis) + hangover 로 말소리 구간을 찾고, ZCR ≈ 2f/fs 확인, 잡음이 커질 때 정확도 변화
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
  return out;
}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답

const rnd = mulberry32(0);

function whiteNoise(n: number): Float32Array {
  return Float32Array.from({ length: n }, () => gauss(rnd));
}

function pinkNoise(n: number): Float32Array {
  // 1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (Paul Kellet의 간단한 필터)
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  return Float32Array.from({ length: n }, () => {
    const w = gauss(rnd);
    b0 = 0.99765 * b0 + w * 0.099046;
    b1 = 0.963 * b1 + w * 0.2965164;
    b2 = 0.57 * b2 + w * 1.0526913;
    return b0 + b1 + b2 + w * 0.1848;
  });
}

function humNoise(n: number): Float32Array {
  // 전원 험: 60 Hz와 배음 120 · 180 Hz
  return Float32Array.from({ length: n }, (_, i) => {
    const t = i / SR;
    return Math.sin(2 * Math.PI * 60 * t) + 0.5 * Math.sin(2 * Math.PI * 120 * t) + 0.3 * Math.sin(2 * Math.PI * 180 * t);
  });
}

function addNoise(s: Float32Array, n: Float32Array, snrDb: number): { x: Float32Array; noise: Float32Array } {
  // 잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다
  const nn = n.subarray(0, s.length);
  const g = Math.sqrt(power(s) / (power(nn) * 10 ** (snrDb / 10)));
  const noise = nn.map((v) => g * v);
  return { x: s.map((v, i) => v + noise[i]), noise };
}

function snrVs(ref: ArrayLike<number>, est: ArrayLike<number>): number {
  // 깨끗한 원본 대비 남은 오차로 잰 SNR (dB)
  let a = 0;
  let b = 0;
  for (let i = 0; i < ref.length; i++) {
    a += ref[i] * ref[i];
    b += (ref[i] - est[i]) ** 2;
  }
  return 10 * Math.log10(a / b);
}


const HOPV = 160;

function energyDb(x: Float32Array): number[] {
  // 25 ms(400개) 프레임, 10 ms 간격의 에너지 (dB) = 10 log10(평균 파워) = 20 log10(RMS)
  const e: number[] = [];
  for (let s = 0; s + 400 <= x.length; s += HOPV) e.push(10 * Math.log10(power(x.subarray(s, s + 400)) + 1e-20));
  return e;
}

// 빈칸 실습 7의 답: 켤 때(T_hi) 더 높고 끌 때(T_lo) 더 낮은 문턱 + hangover
function energyVad(x: Float32Array, hiDb: number = 12, loDb: number = 6, hangSec: number = 0.3, minSpeechSec: number = 0.25): Array<[number, number]> {
  const e = energyDb(x);
  const floor = [...e].sort((a, b) => a - b)[Math.floor(e.length * 0.1)]; // 잡음 바닥 (하위 10%)
  const hang = Math.floor((hangSec * SR) / HOPV);
  const segs: Array<[number, number]> = [];
  let speaking = false;
  let quiet = 0;
  let start = 0;
  e.forEach((v, m) => {
    if (!speaking) {
      if (v > floor + hiDb) [speaking, start, quiet] = [true, m, 0];
    } else if (v > floor + loDb) quiet = 0;
    else if (++quiet > hang) {
      segs.push([start, m - quiet]);
      speaking = false;
    }
  });
  if (speaking) segs.push([start, e.length - 1 - quiet]);
  return segs.map(([a, b]): [number, number] => [(a * HOPV) / SR, ((b + 1) * HOPV) / SR]).filter(([a, b]) => b - a >= minSpeechSec);
}

function frameMask(segs: Array<[number, number]>, total: number): boolean[] {
  // (시작 초, 끝 초) 구간 목록 -> 10 ms 프레임마다 말소리면 true
  const m = new Array<boolean>(Math.floor(total / 0.01) + 1).fill(false);
  for (const [a, b] of segs) for (let i = Math.floor(a / 0.01); i < Math.floor(b / 0.01); i++) m[i] = true;
  return m;
}

const segs = energyVad(clean);
console.log("에너지 VAD 구간:", segs.map(([a, b]) => `(${a.toFixed(2)}, ${b.toFixed(2)})`).join(" "), "| 정답", SPEECH.join("~"));
check(segs.length === 1 && Math.abs(segs[0][0] - SPEECH[0]) < 0.15 && Math.abs(segs[0][1] - SPEECH[1]) < 0.3, "말소리 구간 하나를 0.3초 안으로 찾아야 해요.");

// 수식 검증 5: ZCR = 2f / fs, 백색 잡음은 약 0.5
const zcr = (x: Float32Array): number => {
  let z = 0;
  for (let i = 1; i < x.length; i++) if (x[i - 1] >= 0 !== x[i] >= 0) z++;
  return z / (x.length - 1);
};
let ok = true;
for (const f of [150, 1000, 3000]) {
  const z = zcr(tone(f));
  ok = ok && Math.abs(z - (2 * f) / SR) < 0.005;
  console.log(`${String(f).padStart(5)} Hz 사인파: ZCR ${z.toFixed(4)} | 예측 2f/fs = ${((2 * f) / SR).toFixed(4)}`);
}
const zw = zcr(whiteNoise(SR));
console.log(`백색잡음 ZCR: ${zw.toFixed(3)} (약 0.5)`);
check(ok && Math.abs(zw - 0.5) < 0.05, "ZCR은 2f/fs, 백색 잡음은 약 0.5 입니다.");

// 잡음이 커지면 에너지 VAD 정확도는? (10 ms 프레임 일치율)
const ref = frameMask([SPEECH], clean.length / SR);
const acc: Record<number, number> = {};
for (const snr of [20, 10, 5, 0]) {
  const m = frameMask(energyVad(addNoise(clean, whiteNoise(clean.length), snr).x), clean.length / SR);
  acc[snr] = m.filter((v, i) => v === ref[i]).length / ref.length;
  console.log(`SNR ${String(snr).padStart(2)} dB: 에너지 VAD 일치율 ${(acc[snr] * 100).toFixed(1)}%`);
}
check(acc[20] > 0.9, "깨끗할 때는 90% 이상 일치해야 해요.");

