const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
  return out;
}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답

const rnd = mulberry32(0);

function whiteNoise(n: number): Float32Array {
  return Float32Array.from({ length: n }, () => gauss(rnd));
}

function pinkNoise(n: number): Float32Array {
  // 1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (Paul Kellet의 간단한 필터)
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  return Float32Array.from({ length: n }, () => {
    const w = gauss(rnd);
    b0 = 0.99765 * b0 + w * 0.099046;
    b1 = 0.963 * b1 + w * 0.2965164;
    b2 = 0.57 * b2 + w * 1.0526913;
    return b0 + b1 + b2 + w * 0.1848;
  });
}

function humNoise(n: number): Float32Array {
  // 전원 험: 60 Hz와 배음 120 · 180 Hz
  return Float32Array.from({ length: n }, (_, i) => {
    const t = i / SR;
    return Math.sin(2 * Math.PI * 60 * t) + 0.5 * Math.sin(2 * Math.PI * 120 * t) + 0.3 * Math.sin(2 * Math.PI * 180 * t);
  });
}

function addNoise(s: Float32Array, n: Float32Array, snrDb: number): { x: Float32Array; noise: Float32Array } {
  // 잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다
  const nn = n.subarray(0, s.length);
  const g = Math.sqrt(power(s) / (power(nn) * 10 ** (snrDb / 10)));
  const noise = nn.map((v) => g * v);
  return { x: s.map((v, i) => v + noise[i]), noise };
}

function snrVs(ref: ArrayLike<number>, est: ArrayLike<number>): number {
  // 깨끗한 원본 대비 남은 오차로 잰 SNR (dB)
  let a = 0;
  let b = 0;
  for (let i = 0; i < ref.length; i++) {
    a += ref[i] * ref[i];
    b += (ref[i] - est[i]) ** 2;
  }
  return 10 * Math.log10(a / b);
}


// 주의: Silero VAD 자체는 학습된 신경망(Python 패키지)이라 Node 내장만으로는 못 돌립니다.
//       여기서는 같은 흐름(32 ms 조각 -> 말소리 확률 -> 켜는 문턱 0.5 · 끄는 문턱 0.35 -> 구간)을
//       특징 2개(잡음 바닥 대비 에너지, ZCR)에 로지스틱 회귀 한 층으로 직접 학습해서 보여 줍니다.
const CHUNK = 512; // 16 kHz에서 32 ms

function features(x: Float32Array): number[][] {
  // 조각마다 [잡음 바닥보다 몇 dB 큰가 / 10, 영점 통과율] (바닥 = 전체 조각 에너지의 하위 10%)
  const db: number[] = [];
  const zc: number[] = [];
  for (let s = 0; s + CHUNK <= x.length; s += CHUNK) {
    const c = x.subarray(s, s + CHUNK);
    db.push(10 * Math.log10(power(c) + 1e-20));
    let z = 0;
    for (let i = 1; i < c.length; i++) if (c[i - 1] >= 0 !== c[i] >= 0) z++;
    zc.push(z / CHUNK);
  }
  const floor = [...db].sort((a, b) => a - b)[Math.floor(db.length * 0.1)];
  return db.map((v, i) => [(v - floor) / 10, zc[i]]);
}

// 학습 데이터: 말소리 구간을 아는 합성 클립 40개 (잡음 SNR 0 ~ 20 dB 섞음)
const X: number[][] = [];
const Y: number[] = [];
for (let c = 0; c < 40; c++) {
  const voice = synthVoice(1.2, 100 + 12 * (c % 8), c).map((v) => 0.3 * v);
  const clip = new Float32Array(Math.round(3 * SR));
  clip.set(voice, Math.round(0.9 * SR));
  const { x } = addNoise(clip, c % 2 ? pinkNoise(clip.length) : whiteNoise(clip.length), (c * 7) % 21);
  features(x).forEach((f, i) => {
    X.push(f);
    Y.push(i * CHUNK >= 0.9 * SR && (i + 1) * CHUNK <= 2.1 * SR ? 1 : 0);
  });
}
let w = [0, 0];
let b = 0;
const sigmoid = (z: number): number => 1 / (1 + Math.exp(-z));
for (let it = 0; it < 400; it++) {
  // 경사 하강법: 기울기 = (예측 - 정답) x 입력
  let gw = [0, 0];
  let gb = 0;
  X.forEach((f, i) => {
    const err = sigmoid(w[0] * f[0] + w[1] * f[1] + b) - Y[i];
    gw = [gw[0] + err * f[0], gw[1] + err * f[1]];
    gb += err;
  });
  w = [w[0] - (0.5 * gw[0]) / X.length, w[1] - (0.5 * gw[1]) / X.length];
  b -= (0.5 * gb) / X.length;
}
const prob = (x: Float32Array): number[] => features(x).map((f) => sigmoid(w[0] * f[0] + w[1] * f[1] + b));
const trainAcc = X.filter((f, i) => sigmoid(w[0] * f[0] + w[1] * f[1] + b) > 0.5 === (Y[i] === 1)).length / X.length;
console.log(`학습한 가중치 w = [${w.map((v) => v.toFixed(2)).join(", ")}], b = ${b.toFixed(2)} | 학습 조각 정확도 ${(trainAcc * 100).toFixed(1)}%`);

function timestamps(p: number[], thr: number = 0.5, negThr: number = 0.35, minSilenceMs: number = 300, padMs: number = 30): Array<[number, number]> {
  // Silero와 같은 규칙: 확률 >= thr 이면 켜고, 확률 < negThr 가 minSilenceMs 이상 이어지면 끈다. 앞뒤로 padMs 여유
  const out: Array<[number, number]> = [];
  let on = -1;
  let low = 0;
  p.forEach((v, i) => {
    if (on < 0 && v >= thr) [on, low] = [i, 0];
    else if (on >= 0) {
      low = v < negThr ? low + 1 : 0;
      if (low * (CHUNK / SR) * 1000 >= minSilenceMs) {
        out.push([(on * CHUNK) / SR, ((i - low + 1) * CHUNK) / SR]);
        on = -1;
      }
    }
  });
  if (on >= 0) out.push([(on * CHUNK) / SR, (p.length * CHUNK) / SR]);
  return out.map(([a, e]): [number, number] => [Math.max(0, a - padMs / 1000), e + padMs / 1000]);
}

// 새 소리(앞 학습에 안 쓴 합성 말소리 + 백색 잡음 10 dB)로 시험
const test = addNoise(clean, whiteNoise(clean.length), 10).x;
const p = prob(test);
const ts = timestamps(p);
console.log(`조각 ${p.length}개 (= ${Math.floor(test.length / CHUNK)}) | 구간:`, ts.map(([a, e]) => `${a.toFixed(2)}~${e.toFixed(2)}초`).join(", "));
check(ts.length >= 1 && Math.abs(ts[0][0] - SPEECH[0]) < 0.2 && Math.abs(ts[ts.length - 1][1] - SPEECH[1]) < 0.4, "말소리 구간을 0.2~0.4초 안으로 찾아야 해요.");

const inside = p.filter((_, i) => (i + 0.5) * (CHUNK / SR) > SPEECH[0] + 0.1 && (i + 0.5) * (CHUNK / SR) < SPEECH[1] - 0.1);
const outside = p.filter((_, i) => (i + 0.5) * (CHUNK / SR) < SPEECH[0] - 0.1 || (i + 0.5) * (CHUNK / SR) > SPEECH[1] + 0.1);
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
console.log(`확률 평균: 말소리 안 ${mean(inside).toFixed(2)} · 밖 ${mean(outside).toFixed(2)}`);
check(CHUNK === 512 && p.length === Math.floor(test.length / CHUNK) && mean(inside) > 0.5 && mean(outside) < 0.5, "32 ms = 512 샘플, 말소리 안 확률이 더 높아야 해요.");

pipe.typescript:
// D4 · Part 6 · 미니 프로젝트: 전처리 파이프라인 preprocess() — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d04_pipe.ts
//   16kHz mono → DC · high-pass → 에너지 VAD → 무음으로 잡음 추정 · 스펙트럼 차감 → RMS 정규화 → 말소리 조각 목록
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

function makeClean(): Float32Array {
  // 앞 무음 0.8초 + 합성 말소리 1.8초 + 뒤 무음 0.5초 = 3.1초 (잡음 추정 · VAD 실험용)
  const voice = synthVoice(1.8).map((v) => 0.3 * v);
  const out = new Float32Array(Math.round(3.1 * SR));
  out.set(voice, Math.round(0.8 * SR));
  return out;
}

const clean = makeClean();
const SPEECH: [number, number] = [0.8, 2.6]; // 말소리가 있는 구간(초) = 정답

const rnd = mulberry32(0);

function whiteNoise(n: number): Float32Array {
  return Float32Array.from({ length: n }, () => gauss(rnd));
}

function pinkNoise(n: number): Float32Array {
  // 1/f 잡음: 낮은 주파수일수록 센 '쏴아' 소리 (Paul Kellet의 간단한 필터)
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  return Float32Array.from({ length: n }, () => {
    const w = gauss(rnd);
    b0 = 0.99765 * b0 + w * 0.099046;
    b1 = 0.963 * b1 + w * 0.2965164;
    b2 = 0.57 * b2 + w * 1.0526913;
    return b0 + b1 + b2 + w * 0.1848;
  });
}

function humNoise(n: number): Float32Array {
  // 전원 험: 60 Hz와 배음 120 · 180 Hz
  return Float32Array.from({ length: n }, (_, i) => {
    const t = i / SR;
    return Math.sin(2 * Math.PI * 60 * t) + 0.5 * Math.sin(2 * Math.PI * 120 * t) + 0.3 * Math.sin(2 * Math.PI * 180 * t);
  });
}

function addNoise(s: Float32Array, n: Float32Array, snrDb: number): { x: Float32Array; noise: Float32Array } {
  // 잡음 n의 크기를 맞춰 목표 SNR(dB)로 s에 섞는다
  const nn = n.subarray(0, s.length);
  const g = Math.sqrt(power(s) / (power(nn) * 10 ** (snrDb / 10)));
  const noise = nn.map((v) => g * v);
  return { x: s.map((v, i) => v + noise[i]), noise };
}

function snrVs(ref: ArrayLike<number>, est: ArrayLike<number>): number {
  // 깨끗한 원본 대비 남은 오차로 잰 SNR (dB)
  let a = 0;
  let b = 0;
  for (let i = 0; i < ref.length; i++) {
    a += ref[i] * ref[i];
    b += (ref[i] - est[i]) ** 2;
  }
  return 10 * Math.log10(a / b);
}

const N_FFT = 512;
const HOP = 128;
const HANN = Float64Array.from({ length: N_FFT }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / N_FFT)); // 주기형 Hann

interface Spec {
  re: Float64Array[]; // [프레임][칸]
  im: Float64Array[];
}

function stft(y: Float32Array): Spec {
  // 앞뒤로 N_FFT만큼 0을 붙여 모든 샘플이 같은 횟수 겹치게 한 STFT (칸 수 N_FFT/2 + 1)
  const pad = new Float32Array(y.length + 2 * N_FFT);
  pad.set(y, N_FFT);
  const spec: Spec = { re: [], im: [] };
  for (let s = 0; s + N_FFT <= pad.length; s += HOP) {
    const re = new Float64Array(N_FFT);
    const im = new Float64Array(N_FFT);
    for (let i = 0; i < N_FFT; i++) re[i] = pad[s + i] * HANN[i];
    fft(re, im);
    spec.re.push(re.slice(0, N_FFT / 2 + 1));
    spec.im.push(im.slice(0, N_FFT / 2 + 1));
  }
  return spec;
}

function istft(spec: Spec, length: number): Float32Array {
  // 역변환 + 겹쳐 더하기(overlap-add): 켤레 대칭으로 전체 칸을 채우고 역FFT = conj(FFT(conj X)) / N
  const total = (spec.re.length - 1) * HOP + N_FFT;
  const acc = new Float64Array(total);
  const wsum = new Float64Array(total);
  spec.re.forEach((r, m) => {
    const re = new Float64Array(N_FFT);
    const im = new Float64Array(N_FFT);
    for (let k = 0; k < N_FFT; k++) {
      const kk = k <= N_FFT / 2 ? k : N_FFT - k;
      re[k] = r[kk];
      im[k] = (k <= N_FFT / 2 ? -1 : 1) * spec.im[m][kk]; // conj
    }
    fft(re, im);
    for (let i = 0; i < N_FFT; i++) {
      acc[m * HOP + i] += (re[i] / N_FFT) * HANN[i];
      wsum[m * HOP + i] += HANN[i] * HANN[i];
    }
  });
  return Float32Array.from({ length }, (_, i) => acc[N_FFT + i] / Math.max(wsum[N_FFT + i], 1e-8));
}

function noisePsd(spec: Spec, noiseSec: number = 0.5): Float64Array {
  // 앞쪽 noiseSec초 프레임의 평균 파워 = 잡음 추정 (패딩한 N_FFT만큼 건너뜀)
  const m0 = Math.floor((noiseSec * SR) / HOP);
  const first = Math.floor(N_FFT / HOP);
  const out = new Float64Array(N_FFT / 2 + 1);
  for (let m = first; m < first + m0; m++) for (let k = 0; k < out.length; k++) out[k] += (spec.re[m][k] ** 2 + spec.im[m][k] ** 2) / m0;
  return out;
}


function highpass(x: Float32Array, fc: number): Float32Array {
  // 2차 high-pass(RBJ biquad, Q = 0.707)를 앞으로 한 번, 뒤로 한 번 지나게 함(zero-phase)
  const w0 = (2 * Math.PI * fc) / SR;
  const alphaQ = Math.sin(w0) / (2 * Math.SQRT1_2);
  const c = Math.cos(w0);
  const a0 = 1 + alphaQ;
  const [b0, b1, b2] = [(1 + c) / 2 / a0, -(1 + c) / a0, (1 + c) / 2 / a0];
  const [a1, a2] = [(-2 * c) / a0, (1 - alphaQ) / a0];
  const once = (y: Float64Array): Float64Array => {
    const out = new Float64Array(y.length);
    let [x1, x2, y1, y2] = [0, 0, 0, 0];
    for (let i = 0; i < y.length; i++) {
      out[i] = b0 * y[i] + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2;
      [x2, x1, y2, y1] = [x1, y[i], y1, out[i]];
    }
    return out;
  };
  return Float32Array.from(once(once(Float64Array.from(x)).reverse()).reverse());
}

function vad(x: Float32Array, hiDb: number = 12, loDb: number = 6, hangSec: number = 0.3): Array<[number, number]> {
  // 에너지 VAD: 25 ms 프레임(10 ms 간격) 에너지가 잡음 바닥(하위 10%)보다 hiDb 크면 켜고 loDb 밑으로 hangSec 이어지면 끈다 -> 초 단위 구간
  const hop = 160;
  const e: number[] = [];
  for (let s = 0; s + 400 <= x.length; s += hop) e.push(10 * Math.log10(power(x.subarray(s, s + 400)) + 1e-20));
  const floor = [...e].sort((a, b) => a - b)[Math.floor(e.length * 0.1)];
  const hang = Math.floor((hangSec * SR) / hop);
  const segs: Array<[number, number]> = [];
  let on = -1;
  let quiet = 0;
  e.forEach((v, m) => {
    if (on < 0) {
      if (v > floor + hiDb) [on, quiet] = [m, 0];
    } else if (v > floor + loDb) quiet = 0;
    else if (++quiet > hang) {
      segs.push([(on * hop) / SR, ((m - quiet + 1) * hop) / SR]);
      on = -1;
    }
  });
  if (on >= 0) segs.push([(on * hop) / SR, (e.length * hop) / SR]);
  return segs.filter(([a, b]) => b - a >= 0.25).map(([a, b]): [number, number] => [Math.max(0, a - 0.05), Math.min(x.length / SR, b + 0.05)]); // 앞뒤 50 ms 여유
}

function preprocess(y0: Float32Array, denoise: number = 1): { audio: Float32Array; timestamps: Array<[number, number]> } {
  // 1) DC + high-pass 2) VAD 3) 말소리가 아닌 프레임으로 잡음 추정 -> 스펙트럼 차감 4) RMS -20 dBFS
  const mean = y0.reduce((a, v) => a + v, 0) / y0.length;
  let y = highpass(y0.map((v) => v - mean), 80);
  const timestamps = vad(y);
  const spec = stft(y);
  const first = Math.floor(N_FFT / HOP);
  const nhat = new Float64Array(N_FFT / 2 + 1);
  let count = 0;
  for (let m = first; m < spec.re.length - first; m++) {
    const t = ((m - first) * HOP) / SR;
    if (timestamps.some(([a, b]) => t >= a - 0.05 && t <= b + 0.05)) continue; // 말소리 프레임은 잡음이 아님
    count++;
    for (let k = 0; k < nhat.length; k++) nhat[k] += spec.re[m][k] ** 2 + spec.im[m][k] ** 2;
  }
  if (count > Math.floor((0.2 * SR) / HOP)) {
    spec.re.forEach((r, m) =>
      r.forEach((_, k) => {
        const p = r[k] ** 2 + spec.im[m][k] ** 2;
        const g = Math.sqrt(Math.max(p - (2 * denoise * nhat[k]) / count, 0.02 * p) / Math.max(p, 1e-20));
        r[k] *= g;
        spec.im[m][k] *= g;
      }),
    );
    y = istft(spec, y.length);
  }
  const m2 = y.reduce((a, v) => a + v, 0) / y.length;
  const gain = 10 ** ((-20 - 10 * Math.log10(power(y.map((v) => v - m2)) + 1e-24)) / 20);
  return { audio: y.map((v) => Math.max(-0.99, Math.min(0.99, (v - m2) * gain))), timestamps };
}

function snrBest(ref: Float32Array, est: Float32Array): number {
  // est의 크기(이득)를 가장 잘 맞춘 뒤 잰 SNR(dB): 정규화로 소리 크기가 바뀐 결과를 공정하게 비교
  let dot = 0;
  let ee = 0;
  let rr = 0;
  for (let i = 0; i < ref.length; i++) {
    dot += ref[i] * est[i];
    ee += est[i] * est[i];
    rr += ref[i] * ref[i];
  }
  const g = dot / Math.max(ee, 1e-12);
  let err = 0;
  for (let i = 0; i < ref.length; i++) err += (ref[i] - g * est[i]) ** 2;
  return 10 * Math.log10(rr / err);
}

const noisyPink = addNoise(clean, pinkNoise(clean.length), 5).x; // 핑크 잡음 5 dB
const R = preprocess(noisyPink);
console.log("말소리 구간:", R.timestamps.map(([a, e]) => `(${a.toFixed(2)}, ${e.toFixed(2)})`).join(" "));
const rmsDb = 10 * Math.log10(power(R.audio));
const before = snrBest(clean, noisyPink);
const after = snrBest(clean, R.audio);
console.log(`전처리 전후 RMS: ${(10 * Math.log10(power(noisyPink))).toFixed(1)} -> ${rmsDb.toFixed(1)} dBFS | SNR(이득 보정) ${before.toFixed(2)} -> ${after.toFixed(2)} dB`);
check(R.timestamps.length >= 1 && Math.abs(R.timestamps[0][0] - SPEECH[0]) < 0.25, "말소리 구간을 찾아야 해요.");
check(Math.abs(rmsDb + 20) < 0.5 && after > before, "RMS는 -20 dBFS로 맞추고 SNR은 올라가야 해요.");
